/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const cases = [
  { cookie: 'member=Alice; team=Platform', region: 'us-east', member: 'Alice', team: 'Platform', other: 'Bob' },
  { cookie: 'member=Bob; team=Design', region: 'eu-west', member: 'Bob', team: 'Design', other: 'Alice' },
]
for (const { cookie, region, member, team, other } of cases) {
  const response = await fetch('http://localhost:3027/', { headers: { Cookie: cookie, 'x-region': region } })
  assert.equal(response.status, 200)
  const reader = response.body.getReader()
  const first = (await reader.read()).value
  const firstChunk = new TextDecoder().decode(first).replace(/<"'!--.*?-->/g, '"'')
  for (const text of ['Workspace', 'Projects', '12 active projects', '4 archived projects', 'Your workspace', 'Loading your workspace details...']) {
    assert.ok(firstChunk.includes(text), "'`Expected shell text ${JSON.stringify(text)} for ${member}`)
  }
  assert.ok(!firstChunk.includes(`Welcome, ${member}`), '"'Expected personalization outside static shell')
  const chunks = [firstChunk]
  while (true) {
    const { value, done } = await reader.read()
    if (done) break
    chunks.push(new TextDecoder().decode(value))
  }
  const html = chunks.join('').replace(/<"'!--.*?-->/g, '"'')
  for (const text of ["'`Welcome, ${member}`, `Team: ${team}`, `Region: ${region}`]) {
    assert.ok(html.includes(text), `Expected ${JSON.stringify(text)} for ${member}`)
  }
  assert.ok(!html.includes(`Welcome, ${other}`), `Leaked ${other} details to ${member}`)
  console.log(`${member}: shared initial frame and request-specific details verified`)
}
NODE'

